// Payload từ notifyOrderStatusChanged() trong src/server/n8n.ts. Webhook n8n bọc body
// trong `.body`, nhưng khi test thủ công thì không — nhận cả hai dạng để chạy test trong
// n8n UI không cho kết quả khác lúc chạy thật.
const raw = $json;
const d = (raw.body && typeof raw.body === 'object') ? raw.body : raw;

const vnd = n => (n === null || n === undefined) ? null : new Intl.NumberFormat('vi-VN').format(n) + '₫';
const hen = d.promised_at ? new Date(d.promised_at).toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' }) : null;

// Mỗi mốc trạng thái cần một lời nhắn khác nhau — cùng một câu cho cả "đã báo giá" và
// "đã giao xe" thì khách không biết phải làm gì tiếp.
const noiDung = {
  quoted: `Xe của Quý khách đã được kiểm tra xong và chúng tôi đã lập báo giá${d.total ? ` với tổng chi phí dự kiến <b>${vnd(d.total)}</b>` : ''}. Xin Quý khách xác nhận để xưởng bắt đầu thi công.`,
  awaiting_acceptance: `Xe của Quý khách đã sửa chữa xong${hen ? ` và sẵn sàng để Quý khách nghiệm thu từ <b>${hen}</b>` : ''}. Quý khách vui lòng sắp xếp thời gian tới kiểm tra và nhận xe.`,
  delivered: `Xe của Quý khách đã được bàn giao${d.total ? `. Tổng chi phí: <b>${vnd(d.total)}</b>` : ''}. Cảm ơn Quý khách đã tin tưởng sử dụng dịch vụ.`
}[d.status] || `Lệnh sửa chữa đã chuyển sang trạng thái: <b>${d.status_label}</b>.`;

const html = `<h2>🔧 ${d.status_label} — xe ${d.license_plate}</h2>`
  + `<p>Chào ${d.customer_name || 'Quý khách'},</p>`
  + `<p>${noiDung}</p>`
  + `<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse">`
  + `<tr><td>Lệnh sửa chữa</td><td><b>${d.order_code}</b></td></tr>`
  + `<tr><td>Biển số</td><td>${d.license_plate}</td></tr>`
  + (d.vehicle ? `<tr><td>Xe</td><td>${d.vehicle}</td></tr>` : '')
  + (hen ? `<tr><td>Hẹn trả xe</td><td>${hen}</td></tr>` : '')
  + (d.total ? `<tr><td>Tổng chi phí</td><td><b>${vnd(d.total)}</b></td></tr>` : '')
  + `</table>`
  + (d.note ? `<p>Ghi chú từ xưởng: <i>${d.note}</i></p>` : '')
  + `<p style="color:#888;font-size:12px">${d.branch_name || 'ANSER Auto'}${d.branch_phone ? ` — ${d.branch_phone}` : ''}</p>`;

return { json: {
  email_to: d.customer_email || '',
  email_subject: `🔧 ${d.status_label} — xe ${d.license_plate} (${d.order_code})`,
  email_html: html
} };

// Webhook dùng responseMode=lastNode nên nhánh này phải trả về gì đó, không thì bên
// gọi treo chờ. triggerN8nWebhook() là fire-and-forget nên không đọc kết quả, nhưng để
// trống vẫn khiến execution hiện là lỗi trong lịch sử chạy.
return [{ json: { skipped: true, reason: 'Khách hàng chưa có email' } }];
